def main():
    s=PAGE.read_text(encoding='utf-8')
    if 'css/revision.css' in s:raise SystemExit('Editorial supplement already applied; edit the existing page directly.')
    s=s.replace('</head>','<link rel="stylesheet" href="2026-10-17-black-scholes-model-empirical-validation/css/revision.css"><script defer src="2026-10-17-black-scholes-model-empirical-validation/data/illustrative-observations.js"></script><script defer src="2026-10-17-black-scholes-model-empirical-validation/data/supplement.js"></script><script defer src="2026-10-17-black-scholes-model-empirical-validation/js/revision.js"></script></head>')
    title='The Black–Scholes Model: From Option Pricing to Empirical Evidence'
    s=re.sub(r'<title>.*?</title>',f'<title>{title}</title>',s,count=1)
