    s=re.sub(r'<p class="lead">.*?</p>','<p class="lead">Derive the mathematics. Explore the uncertainty. Test the model against real option prices.</p><p class="hero-intro">A visual journey from a simple contract to Black–Scholes–Merton valuation, followed by a reproducible study of 238,836 held-out SPXW quotes from July–December 2022.</p>',s,count=1)
    meta='''<aside class="provenance" aria-label="Page provenance"><div class="provenance-item"><span aria-hidden="true">📅</span><span><strong>Created:</strong> October 17, 2026</span></div><div class="provenance-item"><span aria-hidden="true">🧰</span><span><strong>Harness:</strong> Codex on Windows</span></div><div class="provenance-item"><span aria-hidden="true">🤖</span><span><strong>Model:</strong> GPT-6 (reported session identity; exact variant unverified)</span></div><div class="provenance-item"><span aria-hidden="true">🧠</span><span><strong>Reasoning:</strong> Configuration not exposed</span></div></aside>'''
    s=re.sub(r'<aside class="provenance".*?</aside>',meta,s,count=1)
    hero='''<svg class="hero-art" viewBox="0 0 1200 150" role="img" aria-label="Conceptual roadmap: a random stock path, a contractual payoff, the pricing formula and a market comparison motif. The small marks are illustrations, not observed data."><g fill="#fffdf7" stroke="#d9ccb8"><rect x="0" y="1" width="282" height="148" rx="12"/><rect x="306" y="1" width="282" height="148" rx="12"/><rect x="612" y="1" width="282" height="148" rx="12"/><rect x="918" y="1" width="282" height="148" rx="12"/></g><g fill="none" stroke-width="3"><path d="M20 100 45 87 70 100 95 68 120 80 145 45 170 64 200 40 250 51" stroke="#087f80"/><path d="M330 102H436L558 32" stroke="#205492"/><path d="M946 108 1168 25" stroke="#a3b4a4" stroke-dasharray="5 5"/></g><g fill="#205492"><circle cx="975" cy="97" r="4"/><circle cx="1020" cy="74" r="4"/><circle cx="1065" cy="66" r="4"/><circle cx="1125" cy="38" r="4"/></g><g fill="#244e64" font-family="Georgia,serif"><text x="645" y="65" font-size="30">C = S e⁻ᑫᵀ N(d₁)</text><text x="679" y="96" font-size="27">− K e⁻ʳᵀ N(d₂)</text></g><g font-family="system-ui,sans-serif" font-size="12" fill="#52666a"><text x="20" y="133">UNCERTAINTY · ILLUSTRATIVE</text><text x="330" y="133">CONTRACT · PAYOFF</text><text x="635" y="133">REPLICATION · VALUE</text><text x="940" y="133">EVIDENCE · COMPARISON MOTIF</text></g></svg>'''
    s=re.sub(r'<svg class="hero-art".*?</svg>',hero,s,count=1)
    s=s.replace('</header>','<nav class="story-route" aria-label="The article story"><a href="#c01">Understand the contract</a><a href="#c03">Understand uncertainty</a><a href="#c04">Derive the model</a><a href="#c06">Inspect the data</a><a href="#c07">Test the model</a><a href="#c08">Understand the limits</a></nav></header>',1)
    titles=[('The idea of an option','What Is an Option?','A small premium buys a right—and creates an obligation for someone else.'),('What determines a price?','Why Does an Option Have a Price?','Separate today’s contract value from tomorrow’s possible payoff.'),('Stock prices as processes','A Stock Price Is Not a Straight Line','Build a language for uncertainty, one random increment at a time.'),('Deriving Black–Scholes–Merton','From Randomness to Black–Scholes','Follow the logic from a changing stock price to a replicating strategy and a price.'),('The Greeks','Understanding the Greeks','Read the local shape of an option’s value and the risks of a moving hedge.'),('Market data &amp; experimental design','Inside the Real Market Data','Inspect the observations, conventions and choices behind the experiment.'),('Two tests, one held-out sample','Does Black–Scholes Match the Market?','Compare two volatility inputs on the same contracts, with calibration kept separate.'),('Where the model breaks down','Where the Model Falls Short','The market’s skew and the model’s assumptions tell different stories.'),('Numerical checks &amp; conclusions','What Survives the Checks?','Numerical identities are testable; empirical conclusions remain conditional.'),('Sources &amp; reproducibility','Reproduce the Research','Follow the sources, code and publication limits back to the calculation.')]
    for old,new,deck in titles:s=s.replace(f'<h2>{old}</h2>',f'<h2>{new}</h2><p class="chapter-deck">{deck}</p>')
    s=s.replace('data-short="Price inputs"','data-short="Price"').replace('data-short="Random paths"','data-short="Uncertainty"').replace('data-short="Data design"','data-short="Real data"').replace('data-short="Empirical tests"','data-short="Market test"')
    terms=[('S','Underlying asset','The thing whose price the option follows.','Here a $100 stock is the teaching asset. In the research, the underlying is the S&amp;P 500 index; quotes are in index points.'),('↗','Call option','A right to buy at the strike.','At expiry, a call with K = $100 pays $20 if the stock is $120, and zero if it is $80.'),('↘','Put option','A right to sell at the strike.','A put with K = $100 pays $20 at a terminal stock price of $80. It pays zero at $120.'),('⇄','Buyer &amp; writer','One pays a premium; one takes the obligation.','The buyer holds the exercise right. The writer receives the premium and owes any contractual payoff. Their pre-cost profits sum to zero.'),('K','Strike price','The exercise price written into the contract.','A $95 call strike lets the holder buy for $95 even if the stock ends at $110. The strike is different from the current market price.'),('T','Expiry &amp; maturity','A date and the time remaining until it.','Expiration is a calendar date. Time to maturity is how long remains: 30 calendar days is T = 30/365 years in this article.'),('$','Option premium','The price paid now for the right.','A $7 premium is an upfront cost, not an additional exercise payment. For a call, exercising still requires paying K. SPX contracts use a $100 multiplier.'),('+','Intrinsic &amp; time value','Immediate-exercise value versus the rest of the premium.','At S = $100, a K = $95 call has $5 intrinsic value. A $7 quoted premium leaves $2 of conventional time value. For European contracts exercise is restricted; with carry and discounting, premium minus immediate intrinsic need not always be positive.'),('≷','Moneyness','Is exercise favorable at the current spot?','A call is in the money when S &gt; K; a put when S &lt; K. At the money means near equality. The other direction is out of the money. Moneyness does not include the premium, so it does not tell you whether the position is profitable.'),('τ','Exercise style','European: at expiry. American: up to expiry.','These names describe exercise rights, not geography. An American holder may exercise early; a European holder cannot. This study selects European SPXW.'),('⇥','Exercise or sell?','Use the contract’s right—or trade the option itself.','Selling an option you own closes your position at a market price. Exercising uses the contractual right; it may surrender remaining time value. Selling to close is different from opening a short writer position.'),('Π','Payoff &amp; net profit','A terminal receipt versus a receipt after cost.','A call payoff of $20 minus a $7 premium gives $13 profit before fees and financing. A zero payoff means a $7 holder loss. The writer has the opposite pre-cost profit.')]
    cards=''.join(f'<details><summary><span class="term-symbol" aria-hidden="true">{symbol}</span>{name}<small>{short}</small></summary><p>{long}</p></details>' for symbol,name,short,long in terms)
    beginner=f'''<div id="beginner-guide"><h3>Options and Option Pricing: A Beginner's Guide</h3><p>Start with a stock trading at $100. An option is a separate contract linked to that stock: it gives its buyer a choice later, in exchange for a price paid now. Open a term to connect the name with a concrete example.</p><nav class="subnav" aria-label="Option chapter contents"><a href="#terminology">Learn the vocabulary</a><a href="#two-outcomes">Try two outcomes</a><a href="#four-positions">Compare four positions</a><a href="#payoff-lab">Explore profit</a></nav><div id="terminology" class="term-grid">{cards}</div></div>
    <figure class="figure-shell contract-figure"><svg viewBox="0 0 1000 175" role="img" aria-label="At inception the buyer pays the option premium to the writer. The writer grants a right on the underlying at strike K, expiring at a specified date. At expiry the writer owes the positive contractual payoff to the buyer."><defs><marker id="contract-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 10 5 0 10" fill="#087f80"/></marker></defs><rect x="20" y="30" width="200" height="115" rx="12" fill="#e8f5cc"/><rect x="780" y="30" width="200" height="115" rx="12" fill="#ffead7"/><g font-size="18" text-anchor="middle"><text x="120" y="78">Option buyer</text><text x="880" y="78">Option writer</text><text x="500" y="28">Today: premium $7</text><text x="500" y="160">Expiry: payoff flows back if positive</text></g><g font-size="13" text-anchor="middle"><text x="120" y="104">Pays for the right</text><text x="880" y="104">Receives premium, owes payoff</text><text x="500" y="91">Underlying stock · Strike K · Expiration date</text></g><g stroke="#087f80" stroke-width="2" marker-end="url(#contract-arrow)"><path d="M230 47H770"/><path d="M770 125H230"/></g></svg><figcaption>Figure A · The premium is paid at inception. The option’s payoff is determined at expiry; exercise and settlement depend on the contract. The example $7 is a teaching assumption.</figcaption></figure>
    <div class="lab" id="two-outcomes"><div class="lab-title"><h3>One $100 stock, two possible futures</h3><span class="teaching-badge">Illustrative outcomes · no probabilities assigned</span></div><p>Keep today’s stock at $100. Move the strike or either future price and see how the right changes. This compares payoffs; two possible outcomes alone do not determine a fair premium.</p><div class="controls"><label>Strike K ($)<output id="begin-k-out"></output><input id="begin-k" type="range" min="70" max="130" value="100"></label><label>Future A: stock ($)<output id="begin-a-out"></output><input id="begin-a" type="range" min="40" max="160" value="80"></label><label>Future B: stock ($)<output id="begin-b-out"></output><input id="begin-b" type="range" min="40" max="160" value="120"></label></div><div class="chart" id="two-outcome-chart"></div><div class="readout" id="two-outcome-result" aria-live="polite"></div><p class="caption">Horizontal axis: two illustrative terminal stock prices. Vertical axis: per-share option payoff ($). Blue = call; teal = put. No premium, probability, interest or trading cost is assumed in these payoffs.</p></div>
    <div class="lab" id="four-positions"><h3>Four positions, one contract logic</h3><p>A buyer pays the premium and receives the payoff; a writer receives the premium and pays the payoff. These four coordinated diagrams use the strike and premium controls in the expiration explorer below.</p><div class="positions">'''+''.join(f'<div><h4>{name}</h4><p class="caption">{desc}</p><div class="chart" id="position-{key}"></div></div>' for key,name,desc in [('lc','Call buyer · long call','Pays premium now; receives max(S_T − K, 0).'),('sc','Call writer · short call','Receives premium now; owes max(S_T − K, 0).'),('lp','Put buyer · long put','Pays premium now; receives max(K − S_T, 0).'),('sp','Put writer · short put','Receives premium now; owes max(K − S_T, 0).')])+'''</div><div class="legend"><span style="--c:#205492">Signed contractual payoff</span><span style="--c:#bc5148">Position profit after premium</span></div><p class="caption">Figure B · x = terminal stock price ($), y = signed payoff/profit ($ per share). Writer payoff is a negative cash flow when the holder exercises. Profit includes the initial premium without financing or fees.</p></div>'''
    s=s.replace('<div class="intro-grid">',beginner+'<div class="intro-grid">',1)
    influence='''<div class="lab" id="influence"><h3>Six inputs feed one pricing model</h3><p>Select an input to trace its effect. The comparison raises that input by a stated amount using the calculator’s current values; it recalculates both prices rather than assuming that every effect has the same sign.</p><div class="influence-grid" id="influence-buttons"></div><div class="influence-result" id="influence-result" aria-live="polite"></div><p class="caption">Figure C · Calculated BSM changes, with other inputs fixed. This is a model sensitivity, not a market forecast. The selected input also becomes the calculator’s sensitivity axis.</p></div>'''
    s=s.replace('<div class="lab"><div class="lab-title"><h3>A living pricing formula',influence+'<div class="lab"><div class="lab-title"><h3>A living pricing formula',1)
    stochastic=r'''<nav class="subnav" aria-label="Stochastic chapter contents"><a href="#random-increments">From shocks to a path</a><a href="#gbm-bridge">Derive the stock model</a><a href="#path-chart">Simulate paths</a><a href="#distribution-chart">See the distribution</a></nav><div class="lab" id="random-increments"><h3>Small shocks accumulate into a path</h3><p>A stock reacts to information that is unknown today. A random model describes uncertainty about that information; it does not say prices move without economic causes. Brownian motion is an idealized continuous limit of many small, centered shocks.</p><div class="controls"><label>Displayed increments<select id="walk-steps"><option value="16">16 coarse increments</option><option value="63">63 increments</option><option value="252">252 fine increments</option></select></label></div><div class="chart" id="walk-chart"></div><div class="flow"><div><b>Shock</b>ΔW ≈ √Δt Z</div><span aria-hidden="true">→</span><div><b>Accumulate</b>W(t) = sum of increments</div><span aria-hidden="true">→</span><div><b>Exponentiate</b>S(t) = S₀ exp[(μ − σ²/2)t + σW(t)]</div></div><p class="caption">Figure D · A single seeded illustrative Brownian path sampled at different resolutions, then the mapping to GBM. The coarse increments are grouped from the same 252-increment realization, so changing resolution does not invent a new history. The plotted segments approximate a Brownian path; actual Brownian motion is not piecewise linear.</p></div>'''
    stochastic+=bridge('gbm-bridge','01 / From proportional changes to a stochastic equation','An additive $1 shock means much more to a $10 stock than to a $1,000 stock. Model the relative change so uncertainty scales with the asset price.',r'μ is instantaneous physical price drift (per year), σ is diffusion volatility, and ΔW has variance Δt.',r'\[\Delta S\approx\mu S\Delta t+\sigma S\sqrt{\Delta t}Z,\quad Z\sim N(0,1).\]',r'<p>Write ΔW = √Δt Z, divide the relative-change approximation by Δt only formally, and take the stochastic limit. The random increment scales with √Δt, not Δt:</p><div class="equation">\[dS=\mu Sdt+\sigma SdW.\]</div>',r'The differential dW is a stochastic increment, not an ordinary differentiable velocity. This is a modeling assumption for continuous prices; jumps and changing volatility are excluded.')
    s=s.replace('<p>An ordinary return',stochastic+'<p>An ordinary return',1)
    # Keep the chapter-level assumptions; replace its five compressed steps with expanded bridges.
    a=s.index('<div class="step"><span>1</span>');b=s.index('</section>',a)
    math=r'''<nav class="math-roadmap" aria-label="Mathematical roadmap"><a href="#math-state"><b>S → V</b>Stock model and value</a><a href="#math-ito"><b>dV</b>Itô’s lemma</a><a href="#math-hedge"><b>Δ</b>Hedged portfolio</a><a href="#math-pde"><b>rΠ</b>No arbitrage → PDE</a><a href="#math-neutral"><b>Q</b>Pricing distribution</a><a href="#math-formula"><b>C, P</b>Option price</a></nav><p class="caption">Figure F · Each arrow is a logical step in replication. It is not a claim that historical returns follow the pricing measure.</p>'''
    math+=bridge('math-state','01 / Why value depends on stock price and time',r'A right to buy becomes more useful as the stock rises. It also changes as the deadline approaches, even if the stock is unchanged.',r'V(S,t) is the option value, τ its fixed expiration, and T = τ − t its remaining maturity. Subscripts denote partial derivatives.',r'\[V=V(S,t),\qquad dS=\mu Sdt+\sigma SdW^P.\]',r'<p>For smooth V, a second-order expansion starts with \(\Delta V\approx V_t\Delta t+V_S\Delta S+\frac12V_{SS}(\Delta S)^2\). A random stock increment is of order √Δt, so its square is of order Δt and cannot be discarded alongside higher-order terms.</p>',r'Time and price are separate state coordinates. The formula assumes constant r, q and σ; if these were additional stochastic state variables, this two-variable description would need expansion.')
    math+=bridge('math-ito','02 / Itô’s lemma keeps the curvature term',r'A curved function responds differently to up and down shocks even when the shocks average to zero. Curvature creates a drift correction.',r'Itô rules: (dW)² = dt in quadratic variation, dt dW = 0, and (dt)² = 0. V_S is delta and V_SS is gamma.',r'\[dV=V_tdt+V_SdS+\tfrac12V_{SS}(dS)^2\]\[=\left(V_t+\mu SV_S+\tfrac12\sigma^2S^2V_{SS}\right)dt+\sigma SV_SdW^P.\]',r'<details><summary>A concrete example: apply the rule to log S</summary><p>For f(S) = log S, f′ = 1/S and f″ = −1/S². Insert both derivatives, not only the first:</p><div class="equation">\[d\log S=\frac{1}{S}(\mu Sdt+\sigma SdW)-\frac{1}{2S^2}\sigma^2S^2dt\]\[=(\mu-\sigma^2/2)dt+\sigma dW.\]</div><p>Integrating gives \(\log(S_\tau/S_t)=(\mu-\sigma^2/2)T+\sigma(W_\tau-W_t)\). With μ = 6% and σ = 25%, log drift is 0.06 − 0.25²/2 = 0.02875, or 2.875% per year, even though expected price growth uses 6%.</p></details>',r'The −σ²/2 term is the difference between mean log growth and instantaneous expected price growth. It is a consequence of curvature, not an arbitrary adjustment.')
    math+=bridge('math-hedge','03 / Construct a hedge and cancel the random term',r'The option and stock respond to the same local price shock. Choose the stock holding so their random exposures offset.',r'Hold one option and short Δ = V_S units of stock. Π = V − ΔS is the marked hedged position. The short stock pays continuous dividends qSΔ dt.',r'\[dG=dV-\Delta(dS+qSdt)\]\[=\underbrace{\sigma S(V_S-\Delta)}_{0}dW^P+\left[V_t+\mu S(V_S-\Delta)+\tfrac12\sigma^2S^2V_{SS}-qS\Delta\right]dt\]\[=\left(V_t+\tfrac12\sigma^2S^2V_{SS}-qSV_S\right)dt.\]',r'<details><summary>Holdings, rebalancing and the self-financing cash account</summary><p>The gain equation uses the current holdings times asset total returns. Differentiating V − ΔS literally also produces −S dΔ − d[Δ,S]. A self-financing cash account funds hedge adjustments, offsetting these rebalancing terms. Treating the marked-value differential as the trading gain without that cash account is incorrect. The stock gain includes qS dt; a short stock position owes that dividend.</p></details>',r'Both the Brownian risk and the physical drift μ cancel when Δ = V_S. This is a local infinitesimal hedge; discrete rebalancing does not cancel all realized risk.')
    math+=bridge('math-pde','04 / No arbitrage turns the hedge into a PDE',r'A self-financing, locally riskless position must earn the financing rate. Otherwise it can be combined with borrowing or lending to create a local arbitrage under the model assumptions.',r'The financing rate is r. The hedge value is Π = V − SV_S, and its locally riskless gain is rΠ dt.',r'\[V_t+\tfrac12\sigma^2S^2V_{SS}-qSV_S=r(V-SV_S).\]',r'<div class="equation">\[V_t+\tfrac12\sigma^2S^2V_{SS}-qSV_S-rV+rSV_S=0\]\[\boxed{V_t+(r-q)SV_S+\tfrac12\sigma^2S^2V_{SS}-rV=0.}\]</div><p>The coefficient of SV_S is r − q because the hedge stock earns dividends as well as changing price.</p>',r'The physical expected return μ is absent from the pricing PDE. Replication removes the stock risk locally; it does not prove that the stock’s actual expected return equals r − q.')
    math+=bridge('math-boundaries','05 / The contract supplies the terminal condition',r'The PDE describes how value evolves before expiry. The promised payoff tells us which solution we need.',r'C is a European call, P a European put; x⁺ means max(x, 0). Discount factors use remaining time T.',r'\[C(S,\tau)=(S-K)^+,\qquad P(S,\tau)=(K-S)^+.\]',r'<p>At zero spot, the call has no value and the put delivers K at expiry: C(0,t) = 0 and P(0,t) = Ke<sup>−rT</sup>. As S grows without bound, C approaches Se<sup>−qT</sup> − Ke<sup>−rT</sup> and P approaches zero. These conditions, with suitable growth conditions, select the economically relevant solution.</p>',r'The payoff is a boundary in time, not the option’s present value. European exercise is essential; an American early-exercise problem has an additional free boundary.')
    math+=bridge('math-neutral','06 / Use a pricing measure, not a return forecast',r'The PDE can be represented as a discounted expectation under a measure that makes discounted total-return trading gains martingales.',r'P denotes the physical measure (and, in price formulas, P also denotes a put; context distinguishes them). Q denotes the risk-neutral pricing measure; W^Q is Brownian motion under Q.',r'\[dS=(r-q)Sdt+\sigma SdW^Q,\quad V=e^{-rT}\mathbb E^Q[H(S_\tau)\mid S_t=S].\]',r'<p>Apply the same log transformation, now with drift r − q, then integrate the Brownian increment:</p><div class="equation">\[\log S_\tau=\log S+(r-q-\sigma^2/2)T+\sigma\sqrt T\,Z,\quad Z\sim N(0,1)\text{ under }Q.\]</div><p>This discounted expectation solves the terminal-value PDE by the Feynman–Kac representation. In particular, \(\mathbb E^Q S_\tau=Se^{(r-q)T}\).</p>',r'Under the physical measure the price drift remains μ; under Q it is r − q. Risk-neutral probabilities are valuation weights. They are not measured real-world probabilities, and neither test estimates physical future stock-return probabilities.')
    math+=bridge('math-integral','07 / Evaluate the discounted call payoff',r'Split the call payoff into the stock delivered when exercise is favorable and the strike paid in that same event.',r'Let a = log S + (r − q − σ²/2)T, b = σ√T and z* = (log K − a)/b. Exercise occurs when Z &gt; z*. φ is the standard normal density and N its CDF.',r'\[C=e^{-rT}\left[e^a\int_{z_*}^{\infty}e^{bz}\phi(z)dz-K\int_{z_*}^{\infty}\phi(z)dz\right].\]',r'<details><summary>Complete the square: every integration step</summary><div class="equation">\[e^{bz}\phi(z)=\frac{e^{-z^2/2+bz}}{\sqrt{2\pi}}=e^{b^2/2}\phi(z-b).\]\[\int_{z_*}^{\infty}e^{bz}\phi(z)dz=e^{b^2/2}\int_{z_*-b}^{\infty}\phi(u)du=e^{b^2/2}N(b-z_*).\]\[\int_{z_*}^{\infty}\phi(z)dz=N(-z_*),\qquad e^{-rT+a+b^2/2}=Se^{-qT}.\]</div><p>Substitute these results into the expectation. Define d₂ = −z* and d₁ = b − z*; the first integral uses N(d₁) and the exercise indicator uses N(d₂).</p></details>',r'The stock-weighted expectation and the exercise probability are different terms. That distinction explains why the formula needs both d₁ and d₂.')
    math+=bridge('math-formula','08 / Read the formula and recover the put',r'The call equals a prepaid stock component minus a discounted strike component, each weighted by the appropriate normal probability.',r'd₁ is a standardized exercise threshold shifted by σ√T; d₂ is the standardized risk-neutral log-price threshold. N(d₂) = Q(Sτ &gt; K). N(d₁) is a stock-value-weighted probability, not the ordinary exercise probability.',r'\[d_1=\frac{\log(S/K)+(r-q+\sigma^2/2)T}{\sigma\sqrt T},\quad d_2=d_1-\sigma\sqrt T.\]\[\boxed{C=Se^{-qT}N(d_1)-Ke^{-rT}N(d_2).}\]\[\boxed{P=Ke^{-rT}N(-d_2)-Se^{-qT}N(-d_1).}\]',r'<details><summary>Put integration and continuous-dividend put–call parity</summary><p>For the put, integrate over Z &lt; z*. The strike integral gives Ke<sup>−rT</sup>N(z*) and the stock integral gives Se<sup>−qT</sup>N(z* − b). Since z* = −d₂ and z* − b = −d₁, this gives the put formula above.</p><p>Pointwise, \((S_\tau-K)^+-(K-S_\tau)^+=S_\tau-K\). Take the discounted Q expectation:</p><div class="equation">\[C-P=e^{-rT}(Se^{(r-q)T}-K)=\boxed{Se^{-qT}-Ke^{-rT}}.\]</div><p>A prepaid forward delivering one stock unit costs Se<sup>−qT</sup>; subtracting the discounted strike replicates the call-minus-put payoff. Matched European exercise, maturity and settlement are required.</p></details>',r'Call delta is e<sup>−qT</sup>N(d₁), so with dividends it is not simply N(d₁). The formula is exact under its assumptions; empirical accuracy depends on parameter choices and whether those assumptions describe the quotes.')
    d1=(log(100/100)+(.05-.02+.2**2/2))/.2;d2=d1-.2;c=100*exp(-.02)*ndtr(d1)-100*exp(-.05)*ndtr(d2)
    math+=rf'''<div class="lab" id="worked-example"><div class="lab-title"><h3>A fully worked call price</h3><span class="teaching-badge">Calculated numerical example · not a market quote</span></div><p>Take a $100 stock and a $100 strike, with one year remaining, σ = 20%, r = 5%, and q = 2%. All rates are annual decimals and r, q are continuously compounded.</p><div class="worked-grid"><div><table><thead><tr><th>Quantity</th><th>Value</th></tr></thead><tbody><tr><td>S, K</td><td>$100, $100</td></tr><tr><td>T</td><td>1 year</td></tr><tr><td>σ, r, q</td><td>0.20, 0.05, 0.02</td></tr><tr><td>σ√T</td><td>0.20</td></tr><tr><td>N(d₁), N(d₂)</td><td>{ndtr(d1):.8f}, {ndtr(d2):.8f}</td></tr></tbody></table></div><div><div class="equation">\[d_1=\frac{{\log(100/100)+(0.05-0.02+0.20^2/2)\cdot1}}{{0.20\sqrt1}}={d1:.4f},\quad d_2={d2:.4f}.\]\[Se^{{-qT}}={100*exp(-.02):.8f},\quad Ke^{{-rT}}={100*exp(-.05):.8f}.\]\[C={100*exp(-.02)*ndtr(d1):.8f}-{100*exp(-.05)*ndtr(d2):.8f}=\boxed{{\${c:.8f}}}.\]</div></div></div><p class="caption">Values computed with the Python normal CDF; rounded only for display. Premium ≈ ${c:.2f} per share before costs. This example includes a nonzero dividend yield and is independent of the historical empirical sample.</p></div>'''
    s=s[:a]+math+s[b:]
    # Data explorer and five complementary figures, all isolated from original outputs.
    data='''<div class="lab" id="real-observations"><div class="lab-title"><h3>Explore 20 Real Options-Market Observations</h3><span class="empirical-badge">Genuine source rows · deliberately limited extract</span></div><p>One observation is one contract on one quote date. These 20 explanatory examples come from the same held-out SPXW sample; they span calls and puts, strikes, maturities and four dates. They are selected to explain fields, not to estimate the full sample’s metrics.</p><p class="caption">Source: <a href="https://historicaldata.net/samples.html">HistoricalData.net</a>. The 34 original fields are preserved, including unavailable quote timestamps. Orange columns contain the provider’s computed IV/Greeks; blue columns contain our derived quantities. Vendor IV is shown for field interpretation and was never used as each evaluated option’s test volatility.</p><div class="table-tools"><label>Option type<select id="example-kind"><option value="all">All</option><option value="call">Calls</option><option value="put">Puts</option></select></label><label>Quote date<select id="example-date"><option value="all">All four dates</option></select></label><button id="example-clear">Clear Filters</button><span id="example-count" class="status" aria-live="polite"></span></div><div class="origin-key"><span>Source observation / contract field</span><span class="vendor">Source-computed quantity</span><span class="ours">Our calculation</span></div><div class="observations-scroll" tabindex="0" role="region" aria-label="Twenty genuine examples; scroll horizontally and vertically"><table id="examples-table"></table></div><p class="caption" id="example-dates"></p><p class="caption">Use a column heading to sort. N/A means genuinely unavailable, never an imputed zero. Source underlying level is kept exactly as supplied; the separate harmonized SPX column is the input used in our pricing.</p><details><summary>Data dictionary: every friendly heading mapped to its original field</summary><div class="dictionary-scroll" tabindex="0" role="region" aria-label="Full example field dictionary" id="example-dictionary"></div></details><div class="note"><strong>Limited explanatory publication.</strong> The provider’s <a href="https://historicaldata.net/terms.html">terms, §3</a> allow limited example rows to explain research and prohibit collections that substitute for the data. Exactly 20 rows are embedded here, with no larger hidden quote panel, no daily-chain extract and no expanding pagination or dataset download. This is our narrow explanatory use of that permission, not a claim that the license guarantees a 20-row allowance.</div></div>'''
    s=s.replace('<div class="lab"><h3>From archive to evaluation sample',data+'<div class="lab"><h3>From archive to evaluation sample',1)
    s=s.replace('<h3>Rates, dividends, volatility: three different decisions</h3>','<h3 id="parameter-design">Rates, dividends, volatility: three different decisions</h3>',1)
    s=s.replace('<div class="table-wrap"><table><thead><tr><th>Object / field', '<nav class="subnav" aria-label="Data chapter contents"><a href="#real-observations">20 source examples</a><a href="#filter-chart">Filtering</a><a href="#parameter-design">Parameter choices</a><a href="#spread-lab">Quote widths</a><a href="#vol-comparison">Historical versus implied σ</a></nav><div class="table-wrap"><table><thead><tr><th>Object / field',1)
    extra6='''<div class="chart-pair"><div class="lab" id="spread-lab"><div class="lab-title"><h3>How wide are the observed quotes?</h3><span class="empirical-badge">Observed quote aggregates</span></div><div class="chart" id="spread-histogram"></div><div class="tooltip" id="spread-info" aria-live="polite">Focus a bar to inspect its count.</div><p class="caption">Ask − bid, in index points, across all 238,836 held-out quotes, July 1–December 30, 2022. Unequal-width buckets are categorical; bar height shows count, not density. Final ≥100 bucket retains the tail.</p></div><div class="lab" id="vol-comparison"><div class="lab-title"><h3>Past volatility meets market pricing</h3><span class="empirical-badge">Estimated quantities from real data</span></div><div class="chart" id="historical-implied-chart"></div><div class="legend"><span style="--c:#205492">Prior 20-return historical σ</span><span style="--c:#087f80">Median ATM midpoint IV</span></div><div class="tooltip" id="vol-comparison-info" aria-live="polite">Focus a date marker for its observations.</div><p class="caption">Annualized %. Historical σ uses only prior returns. Market IV is independently inverted with the same r/q conventions; daily medians pool held-out calls/puts with 0.98 ≤ K/S ≤ 1.02 across eligible maturities. This compares two estimates, not actual future volatility or an independent IV pricing test.</p></div></div>'''
    # Insert before each existing chapter's closing tag without adding sections.
    def append_chapter(text,id,html):
        start=text.index(f'<section id="{id}"');end=text.index('</section>',start);return text[:end]+html+text[end:]
    s=append_chapter(s,'c06',extra6)
    extra7='''<div class="lab" id="price-by-moneyness"><div class="lab-title"><h3>Where prices sit across strikes</h3><span class="empirical-badge">Observed means and held-out model estimates</span></div><div class="controls"><label>Option side<select id="empirical-side"><option value="call">Call</option><option value="put">Put</option></select></label><label>Maturity<select id="empirical-term"><option value="7–21">7–21 days</option><option value="22–45">22–45 days</option><option value="46–90">46–90 days</option></select></label></div><div class="chart" id="moneyness-price-chart"></div><div class="legend"><span style="--c:#205492">Observed midpoint mean</span><span style="--c:#bc5148">Selected Test A/B mean</span></div><div class="tooltip" id="moneyness-info" aria-live="polite"></div><p class="caption">Each marker pools a fixed moneyness × maturity × side group across the 127-date sample; x is the group’s mean K/S. Price in index points. Connecting means guides the eye; it does not interpolate an observed option chain. The main Test A/B selector changes model quantities.</p><h3>Signed residuals reveal the shape of the mismatch</h3><div class="chart" id="residual-moneyness-chart"></div><p class="caption">Same selected observations, mean(model − midpoint) in index points by moneyness. Zero is unbiased within a group. Pooled means can conceal variation over dates and individual contracts.</p></div><div class="lab"><h3>Pricing error grows across maturity buckets</h3><div class="chart" id="maturity-error-chart"></div><div class="legend"><span style="--c:#205492">Test A · historical σ</span><span style="--c:#087f80">Test B · common fitted σ</span></div><p class="caption">Contract-weighted MAE in index points across the original 7–21, 22–45 and 46–90 day bins. These are the unchanged published maturity breakdowns. The date-cluster intervals above show sampling uncertainty by side and maturity.</p></div>'''
    s=append_chapter(s,'c07',extra7)
    # A compact schematic complements the existing actual self-financing simulation.
    hedge='''<div class="flow" role="img" aria-label="Delta hedge cycle: short call, buy delta shares, observe a price move, update delta and rebalance using the cash account"><div><b>Short call</b>Local exposure −Δ</div><span aria-hidden="true">+</span><div><b>Stock hedge</b>Hold +Δ shares</div><span aria-hidden="true">→</span><div><b>Price moves</b>Gamma changes Δ</div><span aria-hidden="true">→</span><div><b>Rebalance</b>Cash funds share change</div></div><p class="caption">Figure E · The simulation below plots this cycle’s changing holdings. The initial call premium finances the stock/cash hedge; finer rebalancing changes terminal residual risk. Playback elsewhere is opt-in and pauses explicitly.</p>'''
    s=s.replace('<div class="lab"><h3>Why a hedge must move</h3>','<div class="lab"><h3>Why a hedge must move</h3>'+hedge,1)
    # Publication description now explicitly allows this single limited extract.
    s=s.replace('We publish grouped statistics and fitted summaries only: no raw archive, daily quote extract, per-contract IV panel or underlying-price history.','We publish grouped statistics, fitted summaries and exactly 20 explanatory source rows: no raw archive, daily-chain extract, larger contract-level IV panel or underlying-price history.')
    s=s.replace('No quote-level panel, contract identifier panel, raw rate curve','No large quote-level panel, contract identifier collection, raw rate curve')
    s=s.replace('No raw input is present in the project.','The only original source observations published are the 20 explanatory rows.')
    PAGE.write_text(s,encoding='utf-8');print('Updated existing article, preserving all ten chapter IDs.')

